#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_subject_renders_and_parses_back_with_the_address_lower_cased() {
        let subject = SsoSubject::new("google", "104938271650293847561", Some("Carol@Example.test"))
            .expect("well-formed");
        assert_eq!(subject.render(), "google:104938271650293847561:carol@example.test");
        assert_eq!(subject.key(), "google:104938271650293847561");
        assert_eq!(SsoSubject::parse(&subject.render()), Some(subject.clone()));
        let bare = SsoSubject::new("github", "583231", None).expect("well-formed");
        assert_eq!(bare.render(), "github:583231");
        assert_eq!(SsoSubject::parse("github:583231"), Some(bare));
    }

    #[test]
    fn an_address_that_cannot_travel_is_dropped_and_a_foreign_string_does_not_parse() {
        let subject = SsoSubject::new("github", "583231", Some("not-an-address")).expect("well-formed");
        assert_eq!(subject.email, None);
        let colon = SsoSubject::new("github", "583231", Some("\"a:b\"@example.test")).expect("well-formed");
        assert_eq!(colon.email, None);
        assert!(SsoSubject::new("", "1", None).is_none());
        assert!(SsoSubject::new("GitHub", "1", None).is_none());
        assert!(SsoSubject::new("github", "", None).is_none());
        for foreign in [
            "",
            "github",
            "opaque-subject-from-the-fork",
            "github:583231:Carol@Example.test",
            "github:583231:no-at-sign",
            "github:583231:a@b:c",
            "github::x@y",
        ] {
            assert!(SsoSubject::parse(foreign).is_none(), "{foreign:?}");
        }
    }
}
